const backToTop=container.querySelector('[data-md-component="top"]');if(backToTop){backToTop.hidden=!(top>0&&scrollDirectionUp);if(backToTop.hidden){backToTop.setAttribute('tabindex','-1');}else{backToTop.removeAttribute('tabindex');}}
